-- SMARTMOVE TRANSPORT SOLUTIONS
-- Oracle schema for the 11 entities in the latest submitted schema diagram.
-- Run as the SMARTMOVE user in SQL Developer. Run this only once on an empty schema.
-- Assumptions added because the diagrams do not define data types or allowed values:
--   * IDs are generated by Oracle.
--   * ROUTE.DURATION_TIME is stored in minutes.
--   * TRIP departure/arrival times are stored as 24-hour strings, e.g. '08:30'.
--   * Password columns store secure hashes from the Java backend, never plaintext passwords.

CREATE TABLE manager (
    manager_id NUMBER GENERATED ALWAYS AS IDENTITY,
    name       VARCHAR2(100) NOT NULL,
    nic        VARCHAR2(20) NOT NULL,
    phone      VARCHAR2(25),
    email      VARCHAR2(254) NOT NULL,
    password   VARCHAR2(255) NOT NULL,
    CONSTRAINT pk_manager PRIMARY KEY (manager_id),
    CONSTRAINT uq_manager_nic UNIQUE (nic),
    CONSTRAINT uq_manager_email UNIQUE (email)
);

CREATE TABLE vehicle (
    vehicle_id       NUMBER GENERATED ALWAYS AS IDENTITY,
    manager_id       NUMBER NOT NULL,
    vehicle_type     VARCHAR2(30) NOT NULL,
    registration_no  VARCHAR2(25) NOT NULL,
    manufacture_year NUMBER(4),
    seat_capacity    NUMBER(3) NOT NULL,
    status           VARCHAR2(20) DEFAULT 'ACTIVE' NOT NULL,
    fuel_type        VARCHAR2(25),
    CONSTRAINT pk_vehicle PRIMARY KEY (vehicle_id),
    CONSTRAINT fk_vehicle_manager FOREIGN KEY (manager_id) REFERENCES manager(manager_id),
    CONSTRAINT uq_vehicle_registration UNIQUE (registration_no),
    CONSTRAINT ck_vehicle_seats CHECK (seat_capacity > 0),
    CONSTRAINT ck_vehicle_year CHECK (manufacture_year IS NULL OR manufacture_year BETWEEN 1950 AND 2100),
    CONSTRAINT ck_vehicle_status CHECK (status IN ('ACTIVE','INACTIVE','MAINTENANCE','RETIRED'))
);

CREATE TABLE driver (
    driver_id  NUMBER GENERATED ALWAYS AS IDENTITY,
    manager_id NUMBER NOT NULL,
    name       VARCHAR2(100) NOT NULL,
    password   VARCHAR2(255) NOT NULL,
    nic        VARCHAR2(20) NOT NULL,
    license_no VARCHAR2(40) NOT NULL,
    phone      VARCHAR2(25),
    email      VARCHAR2(254),
    hire_date  DATE NOT NULL,
    status     VARCHAR2(20) DEFAULT 'ACTIVE' NOT NULL,
    CONSTRAINT pk_driver PRIMARY KEY (driver_id),
    CONSTRAINT fk_driver_manager FOREIGN KEY (manager_id) REFERENCES manager(manager_id),
    CONSTRAINT uq_driver_nic UNIQUE (nic),
    CONSTRAINT uq_driver_license UNIQUE (license_no),
    CONSTRAINT uq_driver_email UNIQUE (email),
    CONSTRAINT ck_driver_status CHECK (status IN ('ACTIVE','INACTIVE','ON_LEAVE'))
);

CREATE TABLE route (
    route_id       NUMBER GENERATED ALWAYS AS IDENTITY,
    manager_id     NUMBER NOT NULL,
    route_name     VARCHAR2(100) NOT NULL,
    start_location VARCHAR2(120) NOT NULL,
    end_location   VARCHAR2(120) NOT NULL,
    distance_km    NUMBER(9,2) NOT NULL,
    duration_time  NUMBER(6) NOT NULL,
    status         VARCHAR2(20) DEFAULT 'ACTIVE' NOT NULL,
    CONSTRAINT pk_route PRIMARY KEY (route_id),
    CONSTRAINT fk_route_manager FOREIGN KEY (manager_id) REFERENCES manager(manager_id),
    CONSTRAINT ck_route_distance CHECK (distance_km > 0),
    CONSTRAINT ck_route_duration CHECK (duration_time > 0),
    CONSTRAINT ck_route_status CHECK (status IN ('ACTIVE','INACTIVE'))
);

CREATE TABLE passenger (
    passenger_id    NUMBER GENERATED ALWAYS AS IDENTITY,
    manager_id      NUMBER NOT NULL,
    name            VARCHAR2(100) NOT NULL,
    nic             VARCHAR2(20),
    email           VARCHAR2(254) NOT NULL,
    password        VARCHAR2(255) NOT NULL,
    phone           VARCHAR2(25),
    passenger_type  VARCHAR2(30) NOT NULL,
    registered_date DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT pk_passenger PRIMARY KEY (passenger_id),
    CONSTRAINT fk_passenger_manager FOREIGN KEY (manager_id) REFERENCES manager(manager_id),
    CONSTRAINT uq_passenger_nic UNIQUE (nic),
    CONSTRAINT uq_passenger_email UNIQUE (email)
);

CREATE TABLE technician (
    technician_id  NUMBER GENERATED ALWAYS AS IDENTITY,
    manager_id     NUMBER NOT NULL,
    name           VARCHAR2(100) NOT NULL,
    phone          VARCHAR2(25),
    email          VARCHAR2(254),
    password       VARCHAR2(255) NOT NULL,
    hire_date      DATE NOT NULL,
    specialization VARCHAR2(100) NOT NULL,
    CONSTRAINT pk_technician PRIMARY KEY (technician_id),
    CONSTRAINT fk_technician_manager FOREIGN KEY (manager_id) REFERENCES manager(manager_id),
    CONSTRAINT uq_technician_email UNIQUE (email)
);

CREATE TABLE trip (
    trip_id         NUMBER GENERATED ALWAYS AS IDENTITY,
    departure_time  VARCHAR2(5) NOT NULL,
    arrival_time    VARCHAR2(5) NOT NULL,
    trip_date       DATE NOT NULL,
    available_seats NUMBER(3) NOT NULL,
    status          VARCHAR2(20) DEFAULT 'SCHEDULED' NOT NULL,
    route_id        NUMBER NOT NULL,
    vehicle_id      NUMBER NOT NULL,
    driver_id       NUMBER NOT NULL,
    CONSTRAINT pk_trip PRIMARY KEY (trip_id),
    CONSTRAINT fk_trip_route FOREIGN KEY (route_id) REFERENCES route(route_id),
    CONSTRAINT fk_trip_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicle(vehicle_id),
    CONSTRAINT fk_trip_driver FOREIGN KEY (driver_id) REFERENCES driver(driver_id),
    CONSTRAINT ck_trip_seats CHECK (available_seats >= 0),
    CONSTRAINT ck_trip_status CHECK (status IN ('SCHEDULED','IN_PROGRESS','COMPLETED','CANCELLED')),
    CONSTRAINT uq_vehicle_trip_time UNIQUE (vehicle_id, trip_date, departure_time),
    CONSTRAINT uq_driver_trip_time UNIQUE (driver_id, trip_date, departure_time)
);

CREATE TABLE booking (
    booking_id   NUMBER GENERATED ALWAYS AS IDENTITY,
    seat_no      VARCHAR2(10) NOT NULL,
    booking_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    price        NUMBER(10,2) NOT NULL,
    status       VARCHAR2(20) DEFAULT 'PENDING' NOT NULL,
    passenger_id NUMBER NOT NULL,
    trip_id      NUMBER NOT NULL,
    CONSTRAINT pk_booking PRIMARY KEY (booking_id),
    CONSTRAINT fk_booking_passenger FOREIGN KEY (passenger_id) REFERENCES passenger(passenger_id),
    CONSTRAINT fk_booking_trip FOREIGN KEY (trip_id) REFERENCES trip(trip_id),
    CONSTRAINT ck_booking_price CHECK (price >= 0),
    CONSTRAINT ck_booking_status CHECK (status IN ('PENDING','CONFIRMED','CANCELLED','COMPLETED'))
);

-- A seat can be reused after cancellation, but not while an earlier booking is active.
CREATE UNIQUE INDEX uq_booking_active_seat
ON booking (
    CASE WHEN status <> 'CANCELLED' THEN trip_id END,
    CASE WHEN status <> 'CANCELLED' THEN seat_no END
);

CREATE TABLE payment (
    payment_id     NUMBER GENERATED ALWAYS AS IDENTITY,
    booking_id     NUMBER NOT NULL,
    manager_id     NUMBER NOT NULL,
    amount         NUMBER(10,2) NOT NULL,
    payment_method VARCHAR2(30) NOT NULL,
    payment_date   DATE DEFAULT SYSDATE NOT NULL,
    payment_status VARCHAR2(20) DEFAULT 'PENDING' NOT NULL,
    CONSTRAINT pk_payment PRIMARY KEY (payment_id),
    CONSTRAINT fk_payment_booking FOREIGN KEY (booking_id) REFERENCES booking(booking_id),
    CONSTRAINT fk_payment_manager FOREIGN KEY (manager_id) REFERENCES manager(manager_id),
    CONSTRAINT uq_payment_booking UNIQUE (booking_id),
    CONSTRAINT ck_payment_amount CHECK (amount >= 0),
    CONSTRAINT ck_payment_status CHECK (payment_status IN ('PENDING','PAID','FAILED','REFUNDED'))
);

CREATE TABLE maintenance (
    maintenance_id   NUMBER GENERATED ALWAYS AS IDENTITY,
    vehicle_id       NUMBER NOT NULL,
    technician_id    NUMBER NOT NULL,
    manager_id       NUMBER NOT NULL,
    maintenance_type VARCHAR2(60) NOT NULL,
    description      VARCHAR2(1000),
    service_date     DATE NOT NULL,
    cost             NUMBER(10,2) DEFAULT 0 NOT NULL,
    next_service_date DATE,
    status           VARCHAR2(20) DEFAULT 'SCHEDULED' NOT NULL,
    CONSTRAINT pk_maintenance PRIMARY KEY (maintenance_id),
    CONSTRAINT fk_maintenance_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicle(vehicle_id),
    CONSTRAINT fk_maintenance_technician FOREIGN KEY (technician_id) REFERENCES technician(technician_id),
    CONSTRAINT fk_maintenance_manager FOREIGN KEY (manager_id) REFERENCES manager(manager_id),
    CONSTRAINT ck_maintenance_cost CHECK (cost >= 0),
    CONSTRAINT ck_maintenance_next_date CHECK (next_service_date IS NULL OR next_service_date >= service_date),
    CONSTRAINT ck_maintenance_status CHECK (status IN ('SCHEDULED','IN_PROGRESS','COMPLETED','OVERDUE'))
);

CREATE TABLE feedback (
    feedback_id   NUMBER GENERATED ALWAYS AS IDENTITY,
    passenger_id  NUMBER NOT NULL,
    trip_id       NUMBER NOT NULL,
    manager_id    NUMBER NOT NULL,
    rating        NUMBER(1) NOT NULL,
    description   VARCHAR2(1000),
    feedback_date DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT pk_feedback PRIMARY KEY (feedback_id),
    CONSTRAINT fk_feedback_passenger FOREIGN KEY (passenger_id) REFERENCES passenger(passenger_id),
    CONSTRAINT fk_feedback_trip FOREIGN KEY (trip_id) REFERENCES trip(trip_id),
    CONSTRAINT fk_feedback_manager FOREIGN KEY (manager_id) REFERENCES manager(manager_id),
    CONSTRAINT ck_feedback_rating CHECK (rating BETWEEN 1 AND 5)
);

COMMENT ON COLUMN route.duration_time IS 'Route duration in minutes.';
COMMENT ON COLUMN trip.departure_time IS 'Local 24-hour time, format HH24:MI.';
COMMENT ON COLUMN trip.arrival_time IS 'Local 24-hour time, format HH24:MI.';
COMMENT ON COLUMN manager.password IS 'Store a salted password hash from the backend, never plaintext.';
COMMENT ON COLUMN driver.password IS 'Store a salted password hash from the backend, never plaintext.';
COMMENT ON COLUMN passenger.password IS 'Store a salted password hash from the backend, never plaintext.';
COMMENT ON COLUMN technician.password IS 'Store a salted password hash from the backend, never plaintext.';

-- Verify the 11 expected tables.
SELECT table_name
FROM user_tables
WHERE table_name IN ('MANAGER','VEHICLE','DRIVER','ROUTE','PASSENGER','TECHNICIAN','TRIP','BOOKING','PAYMENT','MAINTENANCE','FEEDBACK')
ORDER BY table_name;
